"""Migration of the Meridian CRM 4.2 CRMScript division-by-zero semantics."""


def _legacy_numeric(value: object) -> float:
    """Apply legacy numeric-context coercion for supported operand values."""
    if value is None:
        return 0.0
    if isinstance(value, str) and value.strip() == "":
        return 0.0
    return float(value)


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy CRMScript semantics.

    A divisor that coerces to zero yields numeric zero and emits exactly one
    SCRIPT_DIV0 audit event.
    """
    try:
        dividend = _legacy_numeric(a)
    except (TypeError, ValueError, OverflowError):
        dividend = 0.0

    try:
        divisor = _legacy_numeric(b)
    except (TypeError, ValueError, OverflowError):
        divisor = 0.0

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return float(dividend / divisor), []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
